    50		)
    51	
    52		flush := func() error {
    53			if cur == nil {
    54				return nil
    55			}
    56			if !cur.ContentSeen {
    57				return fmt.Errorf("truncated blame record for commit %s at line %d", cur.Hash, cur.EndLine)
    58			}
    59	
    60			block := whyBlock{
    61				StartLine: cur.EndLine,
    62				EndLine:   cur.EndLine,
    63				Commit:    cur.Meta,
    64				CodeLines: []string{cur.LineText},
    65				Detail:    whyDetailCommit,
    66			}
    67	
    68			if len(blocks) > 0 {
    69				last := &blocks[len(blocks)-1]
    70				if last.Commit.Hash == block.Commit.Hash && last.EndLine+1 == block.StartLine {
    71					last.EndLine = block.EndLine
    72					last.CodeLines = append(last.CodeLines, block.CodeLines...)
    73					return nil
    74				}
    75			}
    76	
    77			blocks = append(blocks, block)
    78			return nil
    79		}
    80	
    81		for scanner.Scan() {
    82			line := scanner.Text()
    83			if strings.HasPrefix(line, "\t") {
    84				if cur == nil {
    85					return nil, fmt.Errorf("unexpected content line without header: %q", line)
    86				}
    87				cur.LineText = strings.TrimPrefix(line, "\t")
    88				cur.ContentSeen = true
    89				if err := flush(); err != nil {
    90					return nil, err
    91				}
    92				cur = nil
    93				continue
    94			}
    95	
    96			if strings.TrimSpace(line) == "" {
    97				continue
    98			}
    99	
   100			fields := strings.Fields(line)
   101			if len(fields) >= 3 && isHexCommitHash(fields[0]) {
   102				if err := flush(); err != nil {
   103					return nil, err
   104				}
   105	
   106				endLine, err := strconv.Atoi(fields[2])
   107				if err != nil {
   108					return nil, fmt.Errorf("invalid blame line number %q: %w", fields[2], err)
   109				}
   110	
   111				cur = &whyBlameHeader{
   112					Hash:    fields[0],
   113					EndLine: endLine,
   114					Meta: whyCommitInfo{
   115						Hash:      fields[0],
   116						ShortHash: shortCommitHash(fields[0]),
   117					},
   118				}
   119				continue
   120			}
   121	
   122			if cur == nil {
   123				return nil, fmt.Errorf("unexpected blame metadata without header: %q", line)
   124			}
   125	
   126			if strings.HasPrefix(line, "author ") {
   127				cur.Meta.Author = strings.TrimPrefix(line, "author ")
   128				continue
   129			}
   130			if strings.HasPrefix(line, "summary ") {
   131				cur.Meta.Subject = strings.TrimPrefix(line, "summary ")
   132				continue
   133			}
   134		}
   135	
   136		if err := scanner.Err(); err != nil {
   137			return nil, err
   138		}
   139		if cur != nil {
   140			if !cur.ContentSeen {
   141				return nil, fmt.Errorf("truncated blame record for commit %s at line %d", cur.Hash, cur.EndLine)
   142			}
   143			if err := flush(); err != nil {
   144				return nil, err
   145			}
   146		}
   147	
   148		return blocks, nil
   149	}
   150	
   151	type whyBlameHeader struct {
   152		Hash        string
   153		EndLine     int
   154		Meta        whyCommitInfo
   155		LineText    string
   156		ContentSeen bool
   157	}
   158	
   159	func shortCommitHash(hash string) string {
   160		if len(hash) <= 10 {
   161			return hash
   162		}
   163		return hash[:10]
   164	}
   165	
   166	func isHexCommitHash(hash string) bool {
   167		if len(hash) == 0 {
   168			return false
   169		}
   170		for _, r := range hash {
   171			switch {
   172			case r >= '0' && r <= '9':
   173			case r >= 'a' && r <= 'f':
   174			case r >= 'A' && r <= 'F':
   175			default:
   176				return false
   177			}
   178		}
   179		return true
   180	}

